{
  "type": "object",
  "required": [
    "clientId",
    "tppId",
    "tppName",
    "softwareStatementId",
    "decodedSsa",
    "orgId"
  ],
  "properties": {
    "clientId": {
      "type": "string",
      "pattern": "^.*[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$",
      "description": "The client identifier for the TPP as issued by the Trust Framework"
    },
    "tppId": {
      "type": "string",
      "description": "The identifier used by the API Hub to uniquely identify the TPP"
    },
    "tppName": {
      "type": "string",
      "description": "The TPP name recorded in the Trust Framework"
    },
    "obieTppId": {
      "type": "string",
      "description": "The UK market TPP identifier. This property is not used for CBUAE and is therefore marked as deprecated."
    },
    "softwareStatementId": {
      "type": "string",
      "description": "The software statement identifier for the Client."
    },
    "obieSoftwareStatementId": {
      "type": "string",
      "description": "The UK market software statement identifier. This property is not used for CBUAE and is therefore marked as deprecated."
    },
    "obieSoftwareStatementName": {
      "type": "string",
      "description": "The UK market software statement name. This property is not used for CBUAE and is therefore marked as deprecated."
    },
    "directoryRecord": {
      "type": "string",
      "format": "base64",
      "description": "The latest copy of the TPP directory record retrieve from the CBUAE Trust Framework directory, encoded as a Base 64 string"
    },
    "ssa": {
      "type": "string",
      "description": "The encoded Software Statement Assertion. This property is not used for CBUAE and is therefore marked as deprecated."
    },
    "decodedSsa": {
      "$ref": "#/components/schemas/ConsentManagerAPI.softwareStatementProperties"
    },
    "orgId": {
      "type": "string",
      "pattern": "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$",
      "description": "The organization identifier for the TPP"
    }
  },
  "description": "The TPP record as held by Ozone. If Ozone TPP Connect has been integrated into a directory, the `directoryRecord` provides the TPP's directory record as held by Ozone in base 64 encoded format."
}

{
  "type": "object",
  "properties": {
    "redirect_uris": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "The redirect URIs registered by the TPP at the Trust Framework"
    },
    "client_name": {
      "type": "string",
      "description": "Name of the Client to be presented to the End-User."
    },
    "client_uri": {
      "type": "string",
      "description": "URL of the home page of the Client."
    },
    "logo_uri": {
      "type": "string",
      "description": "URL of the Client logo."
    },
    "jwks_uri": {
      "type": "string",
      "description": "URL of the Client JSON Web Key Set (JWKS) at the Trust Framework."
    },
    "client_id": {
      "type": "string",
      "description": "Unique Client Identifier."
    },
    "roles": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "The roles under which the organization is registered at the Trust Framework."
    },
    "sector_identifier_uri": {
      "type": "string",
      "description": "URL using the https scheme to be used in calculating Pseudonymous Identifiers by the OP. Allows redirect URI values to be grouped, easing registration management."
    },
    "application_type": {
      "type": "string",
      "description": "Client application type."
    },
    "organisation_id": {
      "type": "string",
      "description": "Organization identifier for organization that owns the Client."
    }
  },
  "description": "The decoded software statement retrieved from the Trust Framework that provides\nthe properties of the Client.\n\nPlease note:\n\n- The JSON payload will contain other properties in addition to those listed\nhere. The properties listed here are considered most relevant for activities\nsuch as TPP logo retrieval and JWS verification.\n- The content reflects elements of discovery metadata, which in generally\ndefined as a file rather than an API. Providing constraints such as\n`minLength` and `maxLength` is impractical in this context\n\nThe full software statement record is also available in the Trust Framework.\nPlease also refer the Registration Framework page in the CBUAE standards for\nadditional guidance on these properties."
}
